<template>
	<image v-if="isImageIcon" class="ucs-icon" :src="iconName" :style="imageStyle" mode="aspectFit"
		@tap="onTap" @longpress="onLongPress" />
	<text v-else class="ucs-icon" :style="fontIconStyle" @tap="onTap" @longpress="onLongPress">{{ icon.glyph }}</text>
</template>

<script setup>
	import { computed } from 'vue'
	import { getThemeColor, getFontSize, getIconSize, getIconDefinition } from '../../core/config.js'

	defineOptions({ options: { virtualHost: true } })

	/**
	 * ucs-icon 基础图标组件。
	 *
	 * @description 根据 name 渲染内置/项目字体图标或图片图标，沿用内置 UcsDesignIcons 字体。
	 * 默认字体图标使用 getFontSize 叠加字号偏移；图片图标传入 baseFontSize 后按文字比例缩放。
	 * scaleWithFont 为 false 时，字体和图片图标均保持基础尺寸。
	 * 字体图标响应主题颜色和项目图标映射，图片图标保持原图颜色并使用 aspectFit。
	 * class、style 和其他未声明的原生属性透传至当前根节点，外部 style 可覆盖计算样式。
	 * @property {string} [name=''] 图标名称或图片地址，去除两端空白；未知字体名称显示空字形并保留尺寸。
	 * @property {number} [size=24] 基础图标尺寸，单位 px；非有限值或非正数回退为 24。
	 * @property {boolean} [scaleWithFont=true] 是否允许跟随全局字号变化；关闭时字体和图片均使用规范化后的 size。
	 * @property {number} [baseFontSize] 仅图片图标使用的配套文字基础字号，单位 px，须为有限正数；省略时图片尺寸固定。
	 * @property {string|string[]} [color=['gray-12','gray-10']] 字体图标颜色，支持 core 色阶、外部颜色或一到两项明暗数组。
	 * @event {object} tap 轻触时触发，传递原生事件。
	 * @event {object} click 与 tap 同次触发，顺序为 tap → click；通常只订阅其中一个。
	 * @event {object} longpress 长按时触发，传递原生事件。
	 * @example
	 * <ucs-icon name="home" :size="24" color="primary-6" />
	 * <ucs-icon name="checkmark" :size="20" :scale-with-font="false" />
	 * <ucs-icon name="/static/logo.png" :size="24" :base-font-size="14" />
	 */
	const props = defineProps({
		name: { type: String, default: '' },
		size: { type: Number, default: 24 },
		scaleWithFont: { type: Boolean, default: true },
		baseFontSize: { type: Number, default: undefined },
		color: { type: [String, Array], default: () => ['gray-12', 'gray-10'] }
	})
	const emit = defineEmits(['tap', 'click', 'longpress'])
	const IMAGE_FILE_PATTERN = /\.(png|jpe?g|gif|webp|svg|avif|bmp)(?:[?#].*)?$/i
	/** @type {import('vue').ComputedRef<string>} 规范化后的图标名称或图片地址。 */
	const iconName = computed(() => typeof props.name === 'string' ? props.name.trim() : '')
	/** 按路径、URL 协议或图片扩展名识别图片；普通名称交给 core 查询字形。 */
	const isImageIcon = computed(() => {
		const name = iconName.value
		return !!name && (name.startsWith('/') || name.startsWith('./') || name.startsWith('../') ||
			/^data:image\//i.test(name) || /^blob:/i.test(name) || name.includes('://') || IMAGE_FILE_PATTERN.test(name))
	})
	/** 字体图标使用 core 的内置映射和项目覆盖，图片分支不查询字形。 */
	const icon = computed(() => isImageIcon.value ? { fontFamily: '', glyph: '' } : getIconDefinition(iconName.value))
	/** 规范化基础尺寸，供字体和图片各自的缩放规则使用。 */
	const baseSize = computed(() => Number.isFinite(props.size) && props.size > 0 ? props.size : 24)
	/** 开启缩放时叠加全局字号偏移，容器与字体共用结果，避免重复叠加。 */
	const fontSize = computed(() => props.scaleWithFont ? getFontSize(baseSize.value) : baseSize.value)
	/** 图片仅在允许缩放且提供文字基准时联动；关闭缩放时忽略 baseFontSize。 */
	const imageSize = computed(() => props.scaleWithFont ? getIconSize(baseSize.value, props.baseFontSize) : baseSize.value)
	/** 图片图标占用正方形区域，按 aspectFit 保留图片比例，不通过 color 对图片染色。 */
	const imageStyle = computed(() => ({ width: `${imageSize.value}px`, height: `${imageSize.value}px` }))
	/** 字形、容器和行高使用同一尺寸；清除普通文字的斜体和粗体影响。 */
	const fontIconStyle = computed(() => {
		const size = `${fontSize.value}px`
		return {
			width: size,
			height: size,
			fontFamily: icon.value.fontFamily,
			fontSize: size,
			fontStyle: 'normal',
			fontWeight: 'normal',
			lineHeight: size,
			color: getThemeColor(props.color)
		}
	})

	/** @param {object} event 原生轻触事件，依次转发 tap 和 click。 */
	function onTap(event) {
		emit('tap', event)
		emit('click', event)
	}
	/** @param {object} event 原生长按事件，保持对象不变。 */
	function onLongPress(event) {
		emit('longpress', event)
	}
</script>

<style>
	@font-face {
		font-family: 'UcsDesignIcons';
		src: url('data:font/ttf;charset=utf-8;base64,') format('truetype');
}

	.ucs-icon {
		flex-shrink: 0;
	}

	/* uni-app Vue3 的 text 是行内元素，需显式允许 width/height 生效。 */
	/* #ifndef UNI-APP-X */
	.ucs-icon {
		display: inline-block;
	}
	/* #endif */
</style>
